export const relatedColoringSubjects = slug => (RELATED[slug] || []).map(related => COLORING_SUBJECTS.find(s => s.slug === related))

export function moreColoringDrawings(slug, n) {
  const drawings = COLORING_DRAWINGS[slug] || []
  const index = drawings.findIndex(drawing => drawing.n === n)
  if (index < 0) return []
  return [...drawings.slice(index + 1), ...drawings.slice(0, index)].slice(0, 8)
}
